// Standalone, and deliberately not part of the Expo app's Gradle build: that tree is
// regenerated by `expo prebuild --clean` on every CI run (see README.md).
pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    // Fail rather than fall back to a project-declared repository. A build that can
    // silently resolve from somewhere unexpected is the supply-chain hole this
    // repository pins every action SHA and package version to avoid.
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "mlkit-collector"
include(":collector")
